136	/**
137	 * Opens each selected claim of the sheet that can be opened — a DRAFT not dated inside a closed period —
138	 * giving each the sheet's next number (or the next in its period while period numbering is on) in list order (people in the order they were added, then each
139	 * person's claims in the order they were added) and recording who opened it. Any other selected claim,
140	 * or an id not on the sheet, is left as it is and counted refused.
141	 */
142	public class BulkOpenClaims {
143	    public void open(@PathVariable("sheetId") String sheetId, @RequestBody BulkOpenRequest request,
144	            @HttpHeaderParameter("X-User") String user, ClaimRepository repository, PeriodRepository periods,
145	            SettingRepository settings, SheetRepository sheets, ClaimLog log, Out<BulkOpened> openedOut) {
146	        String sheet = sheetId.trim();
147	        Set<Long> selected = new HashSet<>(request == null || request.ids() == null ? List.of() : request.ids());
148	        selected.remove(null);
149	        List<Claim> claims = repository.findBySheetIdOrderByIdDesc(sheet).stream()
150	                .filter((c) -> selected.contains(c.getId()))
151	                .sorted(Comparator.comparing(Claim::getPersonId).thenComparing(Claim::getId))
152	                .toList();
153	        List<Period> closed = periods.findBySheetId(sheet).stream().filter(Period::isClosed).toList();
154	        List<Claim> opened = new ArrayList<>();
155	        for (Claim claim : claims) {
156	            if (claim.getStatus() != ClaimStatus.DRAFT || closed.stream().anyMatch((p) -> p.contains(claim.getDate()))) {
157	                continue;
158	            }
159	            // As for a single open: holding the sheet's numbers, then the stored status is re-checked so
160	            // a claim another user opened meanwhile is refused here.
161	            ClaimNumbering numbering = ClaimNumbering.hold(sheet, repository, settings, sheets);
162	            if (ClaimStatus.valueOf(repository.storedStatus(claim.getId())) != ClaimStatus.DRAFT) {
163	                continue;
164	            }
165	            claim.setStatus(ClaimStatus.OPEN);
166	            numbering.number(claim, repository, periods);
167	            claim.setOpenedBy(user == null ? "" : user.trim());
168	            repository.save(claim);
169	            log.record(claim, user);
170	            opened.add(claim);
171	        }
172	        openedOut.set(new BulkOpened(opened, selected.size() - opened.size()));
173	    }
174	}
