283	/** A claim's due as it would be fixed now: at the rate its person's grade has in force on the claim's date: amount × rate / 100,
284	 *  rounded half up when the claim is dated before the sheet's policy date (its today when none is set), half to even otherwise,
285	 *  and raised to the sheet's floor (none when no rate applies), plus, when it is overdue (its due-by, fixed when it was created, is
286	 *  before the sheet's today), the sheet's late percent of that floored due for every full 30 days it is overdue, rounded the
287	 *  same way. A correction (a negative amount) gets neither the floor nor the late charge. */
288	final class ClaimDue {
289	    private ClaimDue() {
290	    }
291	    static BigDecimal now(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings,
292	            SheetRepository sheets) {
293	        Person person = people.findById(claim.getPersonId()).orElseThrow();
294	        LocalDate today = sheets.findById(claim.getSheetId()).orElseThrow().getToday();
295	        RoundingMode rounding = settings.rounding(claim.getSheetId(), claim.getDate(), today);
296	        BigDecimal due = rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
297	                .map((r) -> claim.getAmount().multiply(r.getRate())
298	                        .divide(BigDecimal.valueOf(100), 2, rounding))
299	                .orElse(null);
300	        // A correction's due is its amount × rate, rounded, with no floor and no late charge.
301	        if (!claim.isCorrection()) {
302	            due = settings.floored(claim.getSheetId(), due);
303	        }
304	        if (due != null && !claim.isCorrection()) {
305	            LocalDate dueBy = claim.getDueBy();
306	            long spans = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
307	            if (spans > 0) {
308	                due = due.add(due.multiply(settings.latePct(claim.getSheetId())).multiply(BigDecimal.valueOf(spans))
309	                        .divide(BigDecimal.valueOf(100), 2, rounding));
310	            }
311	        }
312	        return due;
313	    }
314	}
