565	/**
566	 * Gives a claim being opened its number. While the sheet's period numbering is on (the period-numbering-from
567	 * setting is a date and the sheet's today is on or after it) that is the next in its period's own sequence,
568	 * <period name>-<n>, or X-<n> for a claim dated in no period; otherwise the sheet's next sheet-wide number.
569	 * {@link #hold} must come first: it holds the sheet's numbers until the change commits or is refused.
570	 */
571	final class ClaimNumbering {
572	    /** The sequence of claims dated in no period. */
573	    static final String NO_PERIOD = "X";
574	    private final boolean byPeriod;
575	    private ClaimNumbering(boolean byPeriod) {
576	        this.byPeriod = byPeriod;
577	    }
578	    /** Decides how the sheet numbers claims opened now, and holds its numbers. */
579	    static ClaimNumbering hold(String sheetId, ClaimRepository claims, SettingRepository settings, SheetRepository sheets) {
580	        Optional<LocalDate> from = settings.periodNumberingFrom(sheetId);
581	        LocalDate today = sheets.findById(sheetId).map((s) -> s.getToday()).orElse(null);
582	        boolean byPeriod = from.isPresent() && today != null && !today.isBefore(from.get());
583	        claims.holdClaimNumbers(sheetId);
584	        return new ClaimNumbering(byPeriod);
585	    }
586	    /** Gives the claim its number. */
587	    void number(Claim claim, ClaimRepository claims, PeriodRepository periods) {
588	        String sheet = claim.getSheetId();
589	        if (!byPeriod) {
590	            claims.takeClaimNumber(sheet);
591	            claim.setNumber(claims.lastClaimNumber(sheet));
592	            return;
593	        }
594	        String key = periods.findBySheetId(sheet).stream().filter((p) -> p.contains(claim.getDate()))
595	                .map(Period::getName).findFirst().orElse(NO_PERIOD);
596	        if (claims.takeSequenceNumber(sheet, key) == 0) {
597	            claims.startSequence(sheet, key);
598	        }
599	        claim.setPeriodNumber(key + "-" + claims.lastSequenceNumber(sheet, key));
600	    }
601	}
