685	/** A claim's status. It starts DRAFT; DRAFT → OPEN → SETTLED; DRAFT or OPEN → VOID. A clerk settling a claim
686	 *  whose due is above the clerk limit moves it OPEN → PENDING instead; a steward approves it (PENDING → SETTLED)
687	 *  or rejects it (PENDING → OPEN). SETTLED and VOID are final. */
688	public enum ClaimStatus {
689	    DRAFT, OPEN, PENDING, SETTLED, VOID;
690	    /** Whether a claim in this status may move to {@code to} by opening, settling or voiding it (approving
691	     *  and rejecting a PENDING claim are checked by {@link #awaitsApproval()}). */
692	    public boolean canBecome(ClaimStatus to) {
693	        return switch (to) {
694	            case OPEN -> this == DRAFT;
695	            case SETTLED, PENDING -> this == OPEN;
696	            case VOID -> this == DRAFT || this == OPEN;
697	            case DRAFT -> false;
698	        };
699	    }
700	    /** Whether a claim in this status waits for a steward to approve or reject it. */
701	    public boolean awaitsApproval() {
702	        return this == PENDING;
703	    }
704	    /** Whether a claim in this status is live: OPEN, or PENDING (which counts as open everywhere). */
705	    public boolean live() {
706	        return this == OPEN || this == PENDING;
707	    }
708	    /** Whether a claim in this status counts toward claimed, due-total and every total. */
709	    public boolean counts() {
710	        return live() || this == SETTLED;
711	    }
