import { useSyncExternalStore } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { heldOn, usePeople } from '../people/people';
import { useFloor, useLatePct, useRoundsHalfUp } from '../settings/settings';
import { claimDueCents } from '../rates/rates';

// Amounts travel as strings with two decimals ("13.50"); sums are added up in whole cents so no
// floating-point error shows.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when opened, the next on the sheet; null for a draft; a voided claim keeps it. */
  number: number | null;
  /** Fixed when settled (two decimals); null while live, or when no rate applied at settling. */
  settledDue: string | null;
  /** The user who opened it; null for a draft. */
  openedBy: string | null;
  /** For a correction (a negative amount), the number of the SETTLED claim it corrects; null otherwise. */
  corrects: number | null;
  /** Given instead of a number when opened while period numbering is on: <period name>-<n>, or X-<n> in no period. */
  periodNumber: string | null;
  /** Fixed when created: its date plus the terms of its person's grade in force on it (the sheet's when the grade has none). */
  dueBy: string;
  /** Its status log, oldest first: each status it has had, who made the change, the sheet's today then and its due
   *  as computed then (null when no rate applied). */
  log: ClaimLogLine[] };
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string | null };
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** A number with up to two decimals; negative only for a correction. */
export const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/** A claim number. */
export const NUMBER = /^\d{1,9}$/;

/** Whether an amount is negative, which makes its claim a correction. */
export const isCorrection = (amount: string) => /^-/.test(amount.trim()) && /[1-9]/.test(amount);

/** A correction must name, by number, a SETTLED claim of the same person; any other claim names none. */
export function correctionError(claims: Claim[], personId: number, amount: string, corrects: string): string | undefined {
  const named = corrects.trim();
  if (named !== '' && !NUMBER.test(named)) return 'The claim corrected must be given by its number.';
  if (!isCorrection(amount)) {
    return named === '' ? undefined : 'Only a correction (a negative amount) names a claim it corrects.';
  }
  if (named === '') return 'A negative amount is a correction: name the settled claim it corrects.';
  const target = claims.find((c) => c.number === Number(named));
  if (!target || target.personId !== personId || target.status !== 'SETTLED') {
    return `A correction must name a settled claim of the same person; claim ${named} is not one.`;
  }
  return undefined;
}

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The active sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet ?? ''),
    queryFn: () => getJson<{ claims: Claim[] }>(`${base(sheet!)}/claims`).then((r) => r.claims),
    enabled: !!sheet,
  });
}

export const addClaim = (sheet: string, user: string, personId: number, input: ClaimInput) =>
  postJson<Claim>(`${base(sheet)}/people/${personId}/claims`, input, user);

/** The quick-add bar: a DRAFT claim dated the sheet's today with an empty note, for the named person
 *  (created with grade A when not on the sheet). */
export const quickAddClaim = (sheet: string, user: string, input: { name: string; amount: string }) =>
  postJson<Claim>(`${base(sheet)}/quick-claims`, input, user);

export const updateClaim = (sheet: string, user: string, id: number, input: ClaimInput) =>
  putJson<Claim>(`${base(sheet)}/claims/${id}`, input, user);

// A claim starts DRAFT; it can be opened, then settled; a DRAFT or OPEN claim can be voided. A clerk
// settling a claim whose due is above the clerk limit sends it to PENDING instead: a steward approves it
// (SETTLED) or rejects it with a reason (back to OPEN). SETTLED and VOID are final. The server refuses a
// change not allowed; the screen refuses it first.
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject';
export const CLAIM_ACTIONS: ClaimAction[] = ['open', 'settle', 'void', 'approve', 'reject'];
const ALLOWED: Record<ClaimAction, ClaimStatus[]> = {
  open: ['DRAFT'], settle: ['OPEN'], void: ['DRAFT', 'OPEN'], approve: ['PENDING'], reject: ['PENDING'],
};
export const canTake = (claim: Claim, action: ClaimAction) => ALLOWED[action].includes(claim.status);

/** Only a DRAFT can be edited; to change an OPEN claim, void it and add a new one. */
export const canEdit = (claim: Claim) => claim.status === 'DRAFT';

/** Four eyes: the user who opened a claim cannot settle it, nor approve it. */
export const selfSettle = (claim: Claim, user: string, action: ClaimAction) =>
  (action === 'settle' || action === 'approve') && claim.openedBy != null && claim.openedBy === user.trim();

/** Only a steward approves or rejects a PENDING claim. */
export const needsSteward = (action: ClaimAction) => action === 'approve' || action === 'reject';

/** Take an action on a claim; a rejection carries its reason. */
export const claimAction = (sheet: string, user: string, id: number, action: ClaimAction, reason = '') =>
  postJson<Claim>(`${base(sheet)}/claims/${id}/${action}`, action === 'reject' ? { reason } : {}, user);

/** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet; it keeps its number and
 *  date. A SETTLED or VOID claim, and a correction (it names a settled claim of its own person), cannot move. */
export const canReassign = (claim: Claim) =>
  (claim.status === 'DRAFT' || live(claim)) && claim.corrects == null;

export const reassignClaim = (sheet: string, user: string, id: number, personId: number) =>
  postJson<Claim>(`${base(sheet)}/claims/${id}/reassign`, { personId }, user);

// The claims ticked for opening together, shared by every person's claim list and the bulk-open bar.
let selected: ReadonlySet<number> = new Set();
const listeners = new Set<() => void>();
const setSelected = (next: ReadonlySet<number>) => {
  selected = next;
  listeners.forEach((l) => l());
};
const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};

/** The selected claim ids, and a toggle and a clear for them. */
export function useSelectedClaims() {
  const ids = useSyncExternalStore(subscribe, () => selected);
  const toggle = (id: number, on: boolean) => {
    const next = new Set(selected);
    if (on) next.add(id);
    else next.delete(id);
    setSelected(next);
  };
  return { ids, toggle, clear: () => setSelected(new Set()) };
}

/** Open the selected claims together: each that can be opened is, numbered in list order; the rest are refused. */
export const bulkOpenClaims = (sheet: string, user: string, ids: number[]) =>
  postJson<{ opened: number; refused: number }>(`${base(sheet)}/bulk-open`, { ids }, user);

/** Whether a claim is live: OPEN, or PENDING (which counts as open in every total). */
export const live = (claim: Claim) => claim.status === 'OPEN' || claim.status === 'PENDING';

/** Whether a claim counts toward claimed, due-total and every total: only live (OPEN, PENDING) and SETTLED do. */
export const counts = (claim: Claim) => live(claim) || claim.status === 'SETTLED';

/** Whether a claim counts toward the live totals: as `counts`, except that a live claim dated within one
 *  of its person's holds counts in none (their SETTLED claims, and claims outside a hold, still do). */
export function useCounts() {
  const people = new Map((usePeople().data ?? []).map((p) => [p.id, p]));
  return (claim: Claim) => counts(claim) && !(live(claim) && heldOn(people.get(claim.personId), claim.date));
}

const cents = (amount: string) => {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const n = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -n : n;
};

/** The amounts of the claims that count (by `counted`, from `useCounts`) added up, shown with two decimals. */
export function total(claims: Claim[], counted: (claim: Claim) => boolean): string {
  const sum = claims.filter(counted).reduce((n, c) => n + cents(c.amount), 0);
  const abs = Math.abs(sum);
  return `${sum < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by, fixed when it was created. */
export function useDueBy() {
  return (claim: Claim) => claim.dueBy;
}

/** Whether a claim is overdue: it is live (OPEN or PENDING) and its due-by is before the sheet's today. */
export function useOverdue() {
  const dueBy = useDueBy();
  const today = useSheetToday();
  return (claim: Claim) => live(claim) && today !== undefined && dueBy(claim) < today;
}

/** Whole days from one date (yyyy-mm-dd) to another. */
export function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86400000);
}

/** A claim's due in cents (see `claimDueCents`) at a rate, with the sheet's floor and, while it is overdue,
 *  the late percent for each full 30 days past its due-by, rounded by the sheet's policy date. */
export function useClaimDue() {
  const halfUp = useRoundsHalfUp();
  const floor = useFloor();
  const latePct = useLatePct();
  const dueBy = useDueBy();
  const overdue = useOverdue();
  const today = useSheetToday();
  return (claim: Claim, rate: string | undefined) => {
    const spans = overdue(claim) && today !== undefined ? BigInt(Math.floor(daysBetween(dueBy(claim), today) / 30)) : 0n;
    return claimDueCents(claim, rate, floor, latePct, spans, halfUp(claim.date));
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import type { Claim } from '../claims/claims';
import { gradeOn, usePeople } from '../people/people';
import { useCurrentSheet, useSheetToday } from '../session/session';

// A rate is a percent with two decimals ("12.50") for a grade from a from-date on (null: from the
// beginning of time); a grade may have several. A date uses the rate whose from-date is the latest on
// or before it; a date before every rate of its grade, or a grade with no rate, has none (n/a).
// Due is worked out in whole cents and hundredths of a percent with BigInt, so no floating-point
// error shows: amount × rate / 100, rounded to two decimals half to even, or half up for a claim dated
// before the sheet's policy date.
export type Rate = { grade: string; rate: string; from: string | null };
export type RateInput = { grade: string; rate: string; from: string };

/** 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,5}(\.\d{1,2})?$/;

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;
export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The active sheet's rates, by grade. */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet ?? ''),
    queryFn: () => getJson<{ rates: Rate[] }>(base(sheet!)).then((r) => r.rates),
    enabled: !!sheet,
  });
}

export const setRate = (sheet: string, user: string, input: RateInput) => postJson<Rate>(base(sheet), input, user);

/** A two-decimal string (may be negative) as a whole number of hundredths. */
export const hundredths = (value: string): bigint => {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const n = BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -n : n;
};

/** Hundredths shown with two decimals. */
export const show = (n: bigint): string => {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
};

/** The due on an amount at a rate, in cents: amount × rate / 100, rounded half to even (or half up). */
export function dueCents(amount: string, rate: string, halfUp = false): bigint {
  return percentOf(hundredths(amount), hundredths(rate), halfUp);
}

/** A percent (hundredths of a percent) of cents, in cents, rounded half to even (or half up). */
export function percentOf(cents: bigint, percent: bigint, halfUp = false): bigint {
  const product = cents * percent; // cents × hundredths of a percent
  const sign = product < 0n ? -1n : 1n;
  const abs = sign * product;
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  const up = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n));
  return sign * (up ? whole + 1n : whole);
}

/** A claim's due in cents: a settled claim's is the one fixed when it was settled; an open or draft
 *  claim's is live, at its grade's rate in force on the claim's date, and at least the sheet's floor
 *  (cents), plus the late charge: the late percent (hundredths of a percent) of that floored due for each
 *  full 30 days it is overdue (`lateSpans`), rounded like due. A correction (a negative amount) has neither
 *  the floor nor the late charge. Both are rounded half up when `halfUp` (the claim is dated before the policy date),
 *  else half to even. Undefined for n/a. */
export function claimDueCents(claim: Claim, rate: string | undefined, floor: bigint, latePct = 0n, lateSpans = 0n, halfUp = false): bigint | undefined {
  if (claim.status === 'SETTLED') return claim.settledDue === null ? undefined : hundredths(claim.settledDue);
  if (rate === undefined) return undefined;
  const due = dueCents(claim.amount, rate, halfUp);
  if (due < 0n || claim.amount.startsWith('-')) return due; // a correction: no floor, no late charge
  const floored = due < floor ? floor : due;
  return floored + percentOf(floored, latePct * lateSpans, halfUp);
}

/** The grade's rate (two decimals) in force on a date (yyyy-mm-dd), or undefined when none applies. */
export function rateOn(rates: Rate[], grade: string | undefined, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** The rate (two decimals) for a grade in force on a date (default: the sheet's today), or undefined. */
export function useGradeRate() {
  const rates = useRates().data ?? [];
  const today = useSheetToday();
  return (grade: string | undefined, date: string | undefined = today) => rateOn(rates, grade, date);
}

/** The rate in force on a date (default: the sheet's today) for the person's grade in force on that date,
 *  looked up by person id. */
export function usePersonRate() {
  const people = usePeople().data ?? [];
  const rateOf = useGradeRate();
  const today = useSheetToday();
  return (personId: number, date: string | undefined = today) =>
    rateOf(gradeOn(people.find((p) => p.id === personId), date), date);
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

export type Person = { id: number; name: string;
  /** The grade in force on the sheet's today (null before all their grades). */
  grade: string | null;
  /** Every grade recorded, by from-date (yyyy-mm-dd; null: from the beginning of time). */
  grades: { from: string | null; grade: string }[];
  version: number;
  /** The date retired from (yyyy-mm-dd); null while not retired. A claim dated after it is refused. */
  retiredFrom: string | null;
  /** Whether they have any hold. */
  held: boolean;
  /** Their holds, by from-date (yyyy-mm-dd, both inclusive; from null: the beginning of time; to null:
   *  open-ended). Their OPEN and PENDING claims dated within one count in no live total. */
  holds: { from: string | null; to: string | null }[];
  /** The ids of the other people on the sheet named as their patrons. */
  patronIds: number[] };
/** An edit carries the version of the person it was loaded from; the server refuses it (409) when
 *  someone else has saved the person since. */
export type PersonInput = { name: string; grade: string; version?: number;
  /** The date the grade applies from (empty: the sheet's today); a person's first grade applies from
   *  the beginning of time. */
  gradeFrom?: string };

/** The person's grade in force on a date (yyyy-mm-dd): the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string | undefined): string | undefined {
  if (person === undefined || date === undefined) return undefined;
  let found: { from: string | null; grade: string } | undefined;
  for (const g of person.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;
export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The active sheet's people, in the order they were added, retired or not (every total counts them). */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet ?? ''),
    queryFn: () => getJson<{ people: Person[] }>(base(sheet!)).then((r) => r.people),
    enabled: !!sheet,
  });
}

export const addPerson = (sheet: string, user: string, input: PersonInput) =>
  postJson<Person>(base(sheet), input, user);

export const updatePerson = (sheet: string, user: string, id: number, input: PersonInput) =>
  putJson<Person>(`${base(sheet)}/${id}`, input, user);

/** The outcome of an import: the counts added and updated, or the numbers of the lines refused
 *  (nothing imported). */
export type ImportResult = { added: number; updated: number; errors: number[] };

/** Imports people pasted as lines of name,grade; a refusal (400) carries the bad line numbers. */
/** Retires a person from a date (empty: the sheet's today); refused (400) when already retired. */
export const retirePerson = (sheet: string, user: string, id: number, from: string) =>
  postJson<Person>(`${base(sheet)}/${id}/retire`, { from }, user);

/** Adds a hold on a person from a date (empty: the sheet's today) to a date (empty: open-ended);
 *  refused (400) when the to-date is before the from-date. */
export const holdPerson = (sheet: string, user: string, id: number, from: string, to: string) =>
  postJson<Person>(`${base(sheet)}/${id}/hold`, { from, to }, user);

/** Whether a date (yyyy-mm-dd) falls within one of the person's holds. */
export const heldOn = (person: Person | undefined, date: string) =>
  !!person?.holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));

/** Names another person on the sheet as the person's patron; refused (400) for themselves or one
 *  already named. */
export const addPatron = (sheet: string, user: string, id: number, patronId: number) =>
  postJson<Person>(`${base(sheet)}/${id}/patrons`, { patronId }, user);

/** Whether a claim dated `date` would be after the person's retirement (and so refused). */
export const afterRetirement = (person: Person | undefined, date: string) =>
  !!person?.retiredFrom && date > person.retiredFrom;

/** Whether retired people are listed too, kept in the URL. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

export const importPeople = (sheet: string, user: string, text: string) =>
  postJson<ImportResult>(`${base(sheet)}/import`, { text }, user);

/** The person open in the editor (by id), kept in the URL. */
export const useEditingPerson = () => useSearchParam('editPerson', asString);
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { useClaimDue, useClaims, useCounts } from '../claims/claims';
import { hundredths, usePersonRate } from '../rates/rates';

// A period is a name, unique on the sheet, and a from and to date (yyyy-mm-dd), inclusive; no two
// periods of a sheet overlap. A claim belongs to the period whose dates contain its date, or to none.
// A period may be closed: its due-total is then the one fixed when it was closed (closedTotal), and
// no claim dated inside it can be added, edited, opened, settled or voided.
// A steward may reopen a closed period, making its due-total live again.
export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string | null };
