import { HomeMain } from '../../slots/defs/homeMain';
import { useClaims } from '../claims/claims';
import { GRADES, usePeople } from '../people/people';
import { usePeriodDue, usePeriods } from '../periods/periods';
import { show } from '../rates/rates';
import { useDueTotal } from '../rates/rates.slot';
import { useCurrentSheet } from '../session/session';

/** The statuses the summary counts claims by (a status no claim can reach counts 0). */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

// The sheet's summary, worked out from the same figures as the lists: per grade, the people on it today
// (retired people left out) and their due-totals added up (n/a as 0); per period, its due-total; per
// status, the count of claims in it.
function Summary() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const periods = usePeriods().data ?? [];
  const dueOf = useDueTotal();
  const periodDue = usePeriodDue();
  if (!sheet) return null;
  const active = people.filter((p) => !p.retiredFrom);
  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table data-testid="summary-grades">
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {show(onGrade.reduce((n, p) => n + (dueOf(p.id) ?? 0n), 0n))}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{show(periodDue(p))}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 40, Component: Summary });
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { usePeople } from '../people/people';
import { show, usePersonRate } from '../rates/rates';
import { useCurrentSheet } from '../session/session';
import { useClaimDue, useClaims, useCounts, useOverdue } from './claims';

function OverdueColumns() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

/** A person's overdue claims that count: how many, and their dues added up in cents (n/a as 0). */
function useOverdueOf() {
  const claims = useClaims().data ?? [];
  const counts = useCounts();
  const overdue = useOverdue();
  const rateOf = usePersonRate();
  const claimDue = useClaimDue();
  return (personId: number) => {
    const late = claims.filter((c) => c.personId === personId && counts(c) && overdue(c));
    const due = late.reduce((n, c) => n + (claimDue(c, rateOf(personId, c.date)) ?? 0n), 0n);
    return { count: late.length, due };
  };
}

// A person's overdue count and overdue-total: their live (OPEN or PENDING) claims that count, due by before the sheet's today.
function PersonOverdue({ personId }: { personId: number }) {
  const { count, due } = useOverdueOf()(personId);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{show(due)}</td>
    </>
  );
}

// The sheet's overdue count and overdue-total: everyone's added up.
function OverdueTotal() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const overdueOf = useOverdueOf();
  if (!sheet) return null;
  const all = people.map((p) => overdueOf(p.id));
  return (
    <section data-testid="rollup-overdue">
      Overdue <strong data-testid="rollup-overdue-count">{all.reduce((n, o) => n + o.count, 0)}</strong>{' '}
      Overdue total <strong data-testid="rollup-overdue-total">{show(all.reduce((n, o) => n + o.due, 0n))}</strong>
    </section>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 30, Component: OverdueColumns }),
  PersonCells.fill({ order: 30, Component: PersonOverdue }),
  HomeMain.fill({ order: 22, Component: OverdueTotal }),
];
import { useState } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { show } from '../rates/rates';
import { useDueTotal } from '../rates/rates.slot';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { addPatron, peopleKey, usePeople } from './people';

function PatronColumns() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th>Add patron</th>
    </>
  );
}

// A person's patrons (names, sorted), their backing (their patrons' due-totals added up, skipping n/a),
// and a picker that names another person on the sheet as a patron. A refusal shows on the row.
function PersonPatrons({ personId }: { personId: number }) {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const people = usePeople().data ?? [];
  const person = people.find((p) => p.id === personId);
  const dueOf = useDueTotal();
  const [choice, setChoice] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (patronId: number) => addPatron(sheet!, user, personId, patronId),
    onSuccess: async () => {
      setChoice('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
    onError: async () => {
      setError('The patron could not be added: not the person themselves, nor one already named.');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
  });

  const patronIds = person?.patronIds ?? [];
  const patrons = people.filter((p) => patronIds.includes(p.id));
  const names = patrons.map((p) => p.name).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const backing = patrons.reduce((n, p) => n + (dueOf(p.id) ?? 0n), 0n);

  const submit = () => {
    setError('');
    if (!choice) {
      setError('Choose a patron.');
      return;
    }
    once(() => add.mutateAsync(Number(choice)));
  };

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{show(backing)}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={choice}
          onChange={(e) => {
            setChoice(e.target.value);
            setError('');
          }}
        >
          <option value="">Choose…</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>
        <button type="button" data-testid="person-patron-add" onClick={submit} disabled={add.isPending}>
          Add
        </button>
        {error && <span data-testid="person-patron-error">{error}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 40, Component: PatronColumns }),
  PersonCells.fill({ order: 40, Component: PersonPatrons }),
];
import { PeopleBar } from '../../slots/defs/peopleBar';
import { NA, show } from '../rates/rates';
import { useDueTotal } from '../rates/rates.slot';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { gradeOn, usePeople } from './people';

/** A CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a quote
 *  or a line break. */
const csv = (value: string) => (/[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value);

// Export the people as a CSV file: a header line, then one line per person in list order, retired
// people included, with the grade in force on the sheet's today, the retired-from date (or nothing)
// and the due-total as shown. Lines end with a line feed.
function ExportPeople() {
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const people = usePeople().data ?? [];
  const dueOf = useDueTotal();
  if (!sheet) return null;

  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const due = dueOf(p.id);
      lines.push([p.name, gradeOn(p, today) ?? p.grade ?? '', p.retiredFrom ?? '', due === undefined ? NA : show(due)]);
    }
    const text = lines.map((l) => l.map(csv).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([text], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };

  return (
    <button type="button" data-testid="export-people" onClick={download}>
      Export CSV
    </button>
  );
}

export const contribution = PeopleBar.fill({ order: 30, Component: ExportPeople });
